        if len(preorder) == 1:
            return root
        left_root_val = preorder[1]
        left_size = postorder.index(left_root_val) + 1
        root.left = self.constructFromPrePost(preorder[1:1 + left_size], postorder[:left_size])
        root.right = self.constructFromPrePost(preorder[1 + left_size:], postorder[left_size:-1])
        return root

class Solution {
public:
    TreeNode* constructFromPrePost(vector<int>& preorder, vector<int>& postorder) {
        if (preorder.empty()) return nullptr;
        TreeNode* root = new TreeNode(preorder[0]);
        if (preorder.size() == 1) return root;
        int left_val = preorder[1];
        int left_size = 0;
        while (postorder[left_size] != left_val) left_size++;
        left_size++;
        vector<int> pre_left(preorder.begin() + 1, preorder.begin() + 1 + left_size);
        vector<int> pre_right(preorder.begin() + 1 + left_size, preorder.end());
        vector<int> post_left(postorder.begin(), postorder.begin() + left_size);
        vector<int> post_right(postorder.begin() + left_size, postorder.end() - 1);
        root->left = constructFromPrePost(pre_left, post_left);
        root->right = constructFromPrePost(pre_right, post_right);
        return root;
    }
};

class Solution {
    public TreeNode constructFromPrePost(int[] preorder, int[] postorder) {
        if (preorder == null || preorder.length == 0) return null;
        TreeNode root = new TreeNode(preorder[0]);
        if (preorder.length == 1) return root;
        int leftVal = preorder[1];
        int leftSize = 0;
        while (postorder[leftSize] != leftVal) leftSize++;
        leftSize++;
        int[] preLeft = Arrays.copyOfRange(preorder, 1, 1 + leftSize);
        int[] preRight = Arrays.copyOfRange(preorder, 1 + leftSize, preorder.length);
        int[] postLeft = Arrays.copyOfRange(postorder, 0, leftSize);
        int[] postRight = Arrays.copyOfRange(postorder, leftSize, postorder.length - 1);
        root.left = constructFromPrePost(preLeft, postLeft);
        root.right = constructFromPrePost(preRight, postRight);
        return root;
    }
}

var constructFromPrePost = function(preorder, postorder) {
    if (!preorder || preorder.length === 0) return null;
    const root = new TreeNode(preorder[0]);
    if (preorder.length === 1) return root;
    const leftVal = preorder[1];
    const leftSize = postorder.indexOf(leftVal) + 1;
    root.left = constructFromPrePost(preorder.slice(1, 1 + leftSize), postorder.slice(0, leftSize));
    root.right = constructFromPrePost(preorder.slice(1 + leftSize), postorder.slice(leftSize, -1));
    return root;
};
